# ---------------------------------------------------------------------------
# 5. Fluent chaining preserves conditionals through properties/theme/encode/coord
# ---------------------------------------------------------------------------


def test_properties_preserves_conditionals():
    """chart.conditional(spec).properties(...) must not drop conditionals."""
    sel = selection_point(fields=["group"], name="propcd_sel")
    cond = sel.when(fm.Color("group")).otherwise(value("#cccccc"))
    chart = _base_chart(sel=sel, cond=cond)
    chart2 = chart.properties(title="Test")
    assert len(chart2._conditionals) == 1
    assert chart2._conditionals[0].selection_name == "propcd_sel"


def test_theme_preserves_conditionals():
    """chart.conditional(spec).theme(t) must not drop conditionals."""
    sel = selection_point(fields=["group"], name="themecd_sel")
    cond = sel.when(fm.Color("group")).otherwise(value("#cccccc"))
    chart = _base_chart(sel=sel, cond=cond)
    chart2 = chart.theme(fm.Theme(background="#000000"))
    assert len(chart2._conditionals) == 1


def test_encode_preserves_conditionals():
    """chart.conditional(spec).encode(size='x:Q') must not drop conditionals."""
    sel = selection_point(fields=["group"], name="enccd_sel")
    cond = sel.when(fm.Color("group")).otherwise(value("#cccccc"))
    chart = _base_chart(sel=sel, cond=cond)
    chart2 = chart.encode(size="x:Q")
    assert len(chart2._conditionals) == 1


def test_coord_preserves_conditionals():
    """chart.conditional(spec).coord(CoordFlip()) must not drop conditionals."""
    sel = selection_point(fields=["group"], name="coordcd_sel")
    cond = sel.when(fm.Color("group")).otherwise(value("#cccccc"))
    chart = _base_chart(sel=sel, cond=cond)
    chart2 = chart.coord(fm.CoordFlip())
    assert len(chart2._conditionals) == 1


# ---------------------------------------------------------------------------
# 6. _clone() produces independent selection/conditional lists (no aliasing)
# ---------------------------------------------------------------------------


def test_clone_selections_are_independent():
    """Mutating the clone's _selections must not affect the original."""
    sel = selection_point(name="clone_sel")
    chart = _base_chart(sel=sel)
    cloned = chart._clone()

    # Mutate cloned list
    extra = selection_interval(name="extra")
    cloned._selections.append(extra)

    assert len(chart._selections) == 1, "original selections must be unchanged after clone mutation"
    assert len(cloned._selections) == 2


def test_clone_conditionals_are_independent():
    """Mutating the clone's _conditionals must not affect the original."""
    sel = selection_point(fields=["group"], name="clonecd_sel")
    cond = sel.when(fm.Color("group")).otherwise(value("#cccccc"))
    chart = _base_chart(sel=sel, cond=cond)
    cloned = chart._clone()

    # Mutate cloned list
    sel2 = selection_point(fields=["x"], name="clonecd_sel2")
    cond2 = sel2.when(fm.Opacity("x")).otherwise(value(0.1))
    cloned._conditionals.append(cond2)

    assert len(chart._conditionals) == 1, (
        "original conditionals must be unchanged after clone mutation"
    )
    assert len(cloned._conditionals) == 2


# ---------------------------------------------------------------------------
# 7. __add__ where ONLY the RHS chart has a selection
# ---------------------------------------------------------------------------


def test_add_only_rhs_has_selection():
    """chart_without_sel + chart_with_sel must produce a merged chart that
    contains the RHS selection."""
    sel = selection_point(fields=["group"], name="rhs_only_sel")
    lhs = _base_chart()
    rhs = _base_chart(sel=sel, mark="line")
    merged = lhs + rhs
    sel_names = {s.name for s in merged._selections}
    assert "rhs_only_sel" in sel_names, f"RHS-only selection missing; got {sel_names}"


def test_add_only_rhs_has_conditional():
    """chart_without_cond + chart_with_cond must preserve the RHS conditional."""
    sel = selection_point(fields=["group"], name="rhs_only_cond_sel")
    cond = sel.when(fm.Color("group")).otherwise(value("#cccccc"))
    lhs = _base_chart()
    rhs = _base_chart(sel=sel, cond=cond, mark="line")
    merged = lhs + rhs
    assert len(merged._conditionals) >= 1, "RHS-only conditional must survive merge"
    assert any(c.selection_name == "rhs_only_cond_sel" for c in merged._conditionals)


# ---------------------------------------------------------------------------
# 8. Triple layer: c1 + c2 + c3 with 3 different selections
# ---------------------------------------------------------------------------


def test_triple_layer_all_three_selections_survive():
    """(c1 + c2 + c3) where each has a distinct selection must preserve all 3."""
    df = _df()
    sels = [selection_point(name=f"triple_{i}") for i in range(3)]
    marks = ["point", "line", "bar"]
    charts = [_base_chart(df, sel=s, mark=m) for s, m in zip(sels, marks)]
    merged = charts[0] + charts[1] + charts[2]
    sel_names = {s.name for s in merged._selections}
    for i in range(3):
        assert f"triple_{i}" in sel_names, f"selection triple_{i} missing; got {sel_names}"


def test_triple_layer_all_three_conditionals_survive():
    """(c1 + c2 + c3) where each has a distinct conditional must preserve all 3."""
    df = _df()
    result_charts = []
    for i in range(3):
        sel = selection_point(fields=["group"], name=f"tricd_{i}")
        cond = sel.when(fm.Color("group")).otherwise(value("#cccccc"))
        c = _base_chart(df, sel=sel, cond=cond, mark=["point", "line", "bar"][i])
        result_charts.append(c)
    merged = result_charts[0] + result_charts[1] + result_charts[2]
    assert len(merged._conditionals) >= 3, (
        f"expected >= 3 conditionals from triple layer; got {len(merged._conditionals)}"
    )


# ---------------------------------------------------------------------------
# 9. Duplicate selection names across LHS and RHS are deduplicated
# ---------------------------------------------------------------------------


def test_add_duplicate_selection_names_deduplicated():
    """When LHS and RHS both have a selection with the same name, the merged
    chart should contain exactly one copy (not two)."""
    sel = selection_point(fields=["group"], name="shared_sel")
    lhs = _base_chart(sel=sel)
    rhs = _base_chart(sel=sel, mark="line")
    merged = lhs + rhs
    sel_names = [s.name for s in merged._selections]
    assert sel_names.count("shared_sel") == 1, (
        f"duplicate selection names should be deduplicated; got {sel_names}"
    )


# ---------------------------------------------------------------------------
# 10. Selections survive through to_spec() serialization
# ---------------------------------------------------------------------------


def test_selections_in_to_spec_json():
    """Selections attached to a chart must appear in the to_spec().to_json()
    output so the Rust renderer receives them."""
    sel = selection_point(fields=["group"], name="spec_sel")
    chart = _base_chart(sel=sel)
    spec_json = chart.to_json()
    parsed = json.loads(spec_json)
    selections = parsed.get("selections", []) or []
    assert len(selections) >= 1, "selections must be present in to_json output"
    assert any(s["name"] == "spec_sel" for s in selections)


def test_conditionals_in_to_spec_json():
    """Conditionals attached to a chart must appear in the to_spec().to_json()
    output."""
    sel = selection_point(fields=["group"], name="speccd_sel")
    cond = sel.when(fm.Color("group")).otherwise(value("#cccccc"))
    chart = _base_chart(sel=sel, cond=cond)
    spec_json = chart.to_json()
    parsed = json.loads(spec_json)
    conditionals = parsed.get("conditionals", []) or []
    assert len(conditionals) >= 1, "conditionals must be present in to_json output"
    assert any(c["selection_name"] == "speccd_sel" for c in conditionals)


# ---------------------------------------------------------------------------
# 11. Merged chart's to_spec includes selections from both sides
# ---------------------------------------------------------------------------


def test_merged_chart_to_spec_includes_both_selections():
    """(chart_a + chart_b).to_spec().to_json() must include selections from
    both sides."""
    df = _df()
    sel_a = selection_point(name="merged_a")
    sel_b = selection_point(name="merged_b")
    chart_a = _base_chart(df, sel=sel_a)
    chart_b = _base_chart(df, sel=sel_b, mark="line")
    merged = chart_a + chart_b
    spec_json = merged.to_json()
    parsed = json.loads(spec_json)
    selections = parsed.get("selections", []) or []
    names = {s["name"] for s in selections}
    assert "merged_a" in names, f"LHS selection missing from merged spec JSON; got {names}"
    assert "merged_b" in names, f"RHS selection missing from merged spec JSON; got {names}"


# ---------------------------------------------------------------------------
# 12. (chart1 + chart2).interactive() scene JSON contains all selections
# ---------------------------------------------------------------------------


def test_add_then_interactive_preserves_all_selections():
    """(chart1 + chart2).interactive() must produce scene JSON with selections
    from both charts."""
    df = _df()
    sel_a = selection_point(fields=["group"], name="int_sel_a")
    sel_b = selection_interval(name="int_sel_b")
    chart_a = _base_chart(df, sel=sel_a)
    chart_b = _base_chart(df, sel=sel_b, mark="line")
    merged = chart_a + chart_b
    ic = InteractiveChart(merged)
    scene = json.loads(ic.scene_json)
    sel_names = {s["name"] for s in scene.get("selections", [])}
    assert "int_sel_a" in sel_names, (
        f"LHS selection missing from interactive scene; got {sel_names}"
    )
    assert "int_sel_b" in sel_names, (
        f"RHS selection missing from interactive scene; got {sel_names}"
    )


# ---------------------------------------------------------------------------
# 13. LayerChart with heterogeneous selections (point + interval on different layers)
# ---------------------------------------------------------------------------


def test_layer_chart_heterogeneous_selections_in_scene():
    """LayerChart where layer 1 has point and layer 2 has interval selection:
    both must appear in the merged scene JSON."""
    df = _df()
    sel_pt = selection_point(fields=["group"], name="hetero_pt")
    sel_iv = selection_interval(name="hetero_iv")
    c1 = _base_chart(df, sel=sel_pt)
    c2 = _base_chart(df, sel=sel_iv, mark="line")
    layer = fm.LayerChart(c1, c2)
    scene_json, _ = _render_scene(layer)
    scene = json.loads(scene_json)
    sel_names = {s["name"] for s in scene.get("selections", [])}
    assert "hetero_pt" in sel_names, (
        f"point selection missing from LayerChart scene; got {sel_names}"
    )
    assert "hetero_iv" in sel_names, (
        f"interval selection missing from LayerChart scene; got {sel_names}"
    )


# ---------------------------------------------------------------------------
# 14. LayerChart with conditional on only one layer
# ---------------------------------------------------------------------------


def test_layer_chart_one_layer_conditional_only():
    """LayerChart where only the second layer has a conditional: it must
    appear in the merged scene JSON."""
    df = _df()
    sel = selection_point(fields=["group"], name="layer1cond")
    cond = sel.when(fm.Color("group")).otherwise(value("#cccccc"))
    c1 = _base_chart(df)
    c2 = _base_chart(df, sel=sel, cond=cond, mark="line")
    layer = fm.LayerChart(c1, c2)
    scene_json, _ = _render_scene(layer)
    scene = json.loads(scene_json)
    conditionals = scene.get("interaction", {}).get("conditionals", [])
    assert any(c["selection_name"] == "layer1cond" for c in conditionals), (
        f"conditional from second layer missing; got {conditionals}"
    )


