# ---------------------------------------------------------------------------
# 16. Multiple add_selection calls accumulate
# ---------------------------------------------------------------------------


def test_multiple_add_selection_calls_accumulate():
    """Multiple .add_selection() calls must accumulate selections, not replace."""
    sel1 = selection_point(name="accum_1")
    sel2 = selection_interval(name="accum_2")
    sel3 = selection_point(fields=["group"], name="accum_3")
    chart = _base_chart().add_selection(sel1).add_selection(sel2).add_selection(sel3)
    assert len(chart._selections) == 3
    names = {s.name for s in chart._selections}
    assert names == {"accum_1", "accum_2", "accum_3"}


# ---------------------------------------------------------------------------
# 17. Composition .theme() preserves child selections
# ---------------------------------------------------------------------------


def test_hconcat_theme_preserves_child_selections():
    """(chart_a | chart_b).theme(t) must preserve selections on child charts."""
    df = _df()
    sel = selection_point(name="htheme_sel")
    c1 = _base_chart(df, sel=sel)
    c2 = _base_chart(df, mark="line")
    composed = c1 | c2
    themed = composed.theme(fm.Theme(background="#111111"))
    # The themed composition's child charts should still have the selection
    has_sel = any(
        any(s.name == "htheme_sel" for s in getattr(c, "_selections", [])) for c in themed.charts
    )
    assert has_sel, "selections on child charts must survive composition .theme()"


def test_hconcat_properties_preserves_child_selections():
    """(chart_a | chart_b).properties(width=400) must preserve selections on child charts."""
    df = _df()
    sel = selection_point(name="hprop_sel")
    c1 = _base_chart(df, sel=sel)
    c2 = _base_chart(df, mark="line")
    composed = c1 | c2
    propped = composed.properties(width=400)
    has_sel = any(
        any(s.name == "hprop_sel" for s in getattr(c, "_selections", [])) for c in propped.charts
    )
    assert has_sel, "selections on child charts must survive composition .properties()"


# ---------------------------------------------------------------------------
# 18. HTML save of layered chart with selections from both layers
# ---------------------------------------------------------------------------


def test_layer_chart_html_contains_all_selections(tmp_path):
    """A LayerChart with selections on both layers, saved as HTML, must have
    both selections in the embedded scene JSON."""
    df = _df()
    sel_a = selection_point(fields=["group"], name="html_layer_a")
    sel_b = selection_interval(name="html_layer_b")
    c1 = _base_chart(df, sel=sel_a)
    c2 = _base_chart(df, sel=sel_b, mark="line")
    layer = fm.LayerChart(c1, c2)
    out = tmp_path / "layer_sels.html"
    layer.interactive().save(str(out))
    content = out.read_text()
    assert "html_layer_a" in content, "LHS selection name missing from HTML"
    assert "html_layer_b" in content, "RHS selection name missing from HTML"


# ---------------------------------------------------------------------------
# 19. __add__ with different data preserves selections
# ---------------------------------------------------------------------------


def test_add_different_data_preserves_selections():
    """chart1 + chart2 with different DataFrames: selections must survive the
    diagonal concat data-merge path."""
    df1 = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0], "group": ["a", "b"]})
    df2 = pl.DataFrame({"x": [5.0, 6.0], "y": [7.0, 8.0], "group": ["c", "d"]})
    sel_a = selection_point(fields=["group"], name="diff_data_a")
    sel_b = selection_point(fields=["group"], name="diff_data_b")
    c1 = _base_chart(df1, sel=sel_a)
    c2 = _base_chart(df2, sel=sel_b, mark="line")
    merged = c1 + c2
    sel_names = {s.name for s in merged._selections}
    assert "diff_data_a" in sel_names
    assert "diff_data_b" in sel_names
